import type { System } from '../../Engine/System';
import type { World } from '../../Engine/World';
import { BUILDING_CONFIG } from '../Config/BuildingConfig';
import { HallEvents } from '../HallEvents';
import { GameData } from '../../Core/Data/GameData';
import { gridToWorld } from '../Config/GridConfig';
import { BuildingEntity } from '../Entity/BuildingEntity';

export interface BuildRequestPayload {
    typeId: string;
    gridX: number;
    gridY: number;
}

export class BuildSystem implements System {
    private _world: World = null!;

    // 注意：构造函数不需要注入 GridMap 了！

    onStart(world: World): void {
        this._world = world;
        world.bus.on(HallEvents.BUILD_REQUEST, this._onBuildRequest, this);
    }

    onDestroy(world: World): void {
        world.bus.off(HallEvents.BUILD_REQUEST, this._onBuildRequest, this);
        this._world = null!;
    }

    onTick(): void {}

    private _onBuildRequest(payload: BuildRequestPayload): void {
        // 1. 依然需要查重（因为 Player 可能连点两次），但这里是通过发事件去查，或者直接依赖接口
        // 为了简单，你可以在这里留个引用查一下，但真正严谨的做法是校验通过直接发
        // 先假设通过校验
        
        const cfg = BUILDING_CONFIG[payload.typeId];
        if (!cfg) return;

        // 2. 扣钱（可抽离到 EconomySystem，这里为了直观直接扣）
        const coins = GameData.profile.data.coins;
        if (coins < cfg.cost) return;
        
        GameData.profile.data.coins -= cfg.cost;
        GameData.profile.save();
        this._world.bus.emit(HallEvents.COIN_CHANGED, GameData.profile.data.coins);

        // 3. 造实体
        const b = this._world.acquire('building', () => new BuildingEntity());
        b.reset(); 
        b.typeId = payload.typeId;
        b.gridX = payload.gridX;
        b.gridY = payload.gridY;
        
        const pos = gridToWorld(payload.gridX, payload.gridY);
        b.x = pos.x;
        b.y = pos.y;

        // 4. 进 World（触发渲染）
        this._world.add(b);

        // 5. 广播完成，彻底不管 GridMap
        this._world.bus.emit(HallEvents.BUILD_COMPLETED, b);
    }
}